import sys; sys.path.insert(0,'.')
from model import *
files=['train/A3_vref_op1.csv','train/A3_amb_op1.csv','train/A3_amb_op2.csv','train/A3_vref_op3.csv','train/A3_load_op2.csv']
def feats(D,L,step=5):
    n=len(D['V']); idx=np.arange(L,n,step)
    cols=[np.ones(len(idx))]
    for k in range(1,L+1):
        j=idx-k*step
        cols+= [D['P'][j],D['Q'][j],D['V'][j]-D['V'][0],D['th'][j]-D['th'][0],D['S'][j]-D['S'][0]]
    return np.column_stack(cols), idx
for L in [1,2,3]:
  for f in files:
    D=load(f); X,idx=feats(D,L)
    for nm in ['P','Q']:
        y=D[nm][idx]
        c=np.linalg.lstsq(X,y,rcond=None)[0]
        print(L,f.split('/')[1],nm,'resid',np.std(y-X@c).round(6),'ystd',np.std(y).round(5))

